const Intro = () => {
  return (
    <div className="intro">
      <div className="container">
        <div className="intro_inner">
          <h1>Строим будущее —<br />из настоящего дерева</h1>
          <h5>Со сроком службы более 20 лет<br />по заводским ценам</h5>
        </div>
      </div>
    </div>
  );
};

export default Intro;
